    "level_in_dbm_dbw": "Un nivel en dBm, dBW, vatios, dBV, dBmV, dBµV o voltios eficaces expresado en cada una de las demás, sobre una impedancia Z: 50 Ω en radio, 75 en vídeo y TV, 600 en audio antiguo; con su tensión de pico y de pico a pico, y la corriente. Dibujado entre los niveles de señales habituales. O una ganancia o pérdida: en dB como razón de potencia y de tensión, o una razón en dB.",
