    "motion_in_line_at": "Movimiento rectilíneo con aceleración constante: escribe tres cualesquiera de s, el desplazamiento, u, la velocidad inicial, v, la velocidad final, a, la aceleración, y t, el tiempo, y se calculan los otros dos. Una velocidad hallada a partir de su cuadrado puede tener cualquier sentido: se dan ambos.",
    "projectile": "Proyectil",
    "something_thrown_at_speed": "Algo lanzado a una velocidad y un ángulo sobre el suelo, desde una altura, sin aire: cuánto tiempo vuela, hasta dónde llega, qué altura alcanza y a qué velocidad cae; su trayectoria dibujada. El ángulo en la unidad en uso.",
    "relative_velocity": "Velocidad relativa",
    "two_things_moving_each": "Dos objetos en movimiento, cada uno a una velocidad y un rumbo: a qué velocidad y en qué dirección se mueve uno visto desde el otro, con dibujo. O una barca que cruza un río de anchura d a una velocidad v respecto al agua, con corriente u: apuntando en perpendicular, cuánto tarda y cuánto río abajo llega; y el rumbo aguas arriba que la lleva en perpendicular. Rumbos desde el este, en sentido antihorario, en la unidad en uso.",
