    "circular_motion": "Movimiento circular",
    "going_round_circle_of": "Girar en una circunferencia de radio r a velocidad constante, a partir de su velocidad, periodo o revoluciones por minuto: los otros dos, la velocidad angular y la frecuencia, la aceleración centrípeta y, para una masa, la fuerza que la mantiene.",
