    "orbits": "Órbitas",
    "satellite_or_planet_going": "Un satélite o un planeta que gira alrededor de un cuerpo de masa M y radio R, según la tercera ley de Kepler: a partir de su altura sobre la superficie, de su periodo, o de sus alturas mínima y máxima, una elipse: el tamaño de su órbita, su periodo y su velocidad, en el punto más cercano y el más lejano, por la ecuación vis-viva; con dibujo. La Tierra si no se indica, 5.972e24 kg y 6.371e6 m; el Sol es 1.989e30 kg y 6.957e8 m. Una órbita geoestacionaria tarda 86164 s.",
    "nearest": "Mínima",
