    "farthest": "Máxima",
    "rocket_equation": "Ecuación del cohete",
    "tsiolkovsky_s_speed_rocket": "La de Tsiolkovski: la velocidad que gana un cohete al quemar su combustible, según su velocidad de escape v<sub>e</sub>, o su impulso específico I<sub>sp</sub>, y su masa llena, m<sub>0</sub>, y vacía, m<sub>f</sub>; su velocidad dibujada mientras quema. Con el tiempo de combustión, su empuje, su aceleración inicial y final, y el Δv restante subiendo en vertical contra g. El I<sub>sp</sub> de un motor de queroseno es de unos 300 s, el de uno de hidrógeno 450; llegar a órbita requiere unos 9400 m/s.",
