    "inclined_plane": "Plano inclinado",
    "mass_on_slope_of": "Una masa en una pendiente de ángulo θ con rozamiento μ: su peso, la fuerza normal, la fuerza a lo largo de la pendiente, el rozamiento y la aceleración, y si desliza.",
    "masses_over_pulley": "Masas en una polea",
    "two_masses_on_string": "Dos masas unidas por una cuerda que pasa por una polea, m<sub>1</sub> colgando y m<sub>2</sub> también colgando, como la máquina de Atwood, sobre una mesa o sobre una pendiente de ángulo θ, con rozamiento μ: su aceleración, hacia dónde se mueven, la tensión de la cuerda y si el rozamiento las retiene; con dibujo. Con una distancia d, a qué velocidad van al recorrerla y cuánto tardan. Con la masa de la polea, un disco, también gira.",
