    "torque_and_levers": "Momento y palancas",
    "turning_of_force_f": "El momento de una fuerza F aplicada a r de un eje, a θ de la barra, un ángulo recto si no se indica; o una palanca en equilibrio, a partir de una carga y su distancia al fulcro: la fuerza a otra distancia y cuánto la multiplica.",
