    "in_si_units_or": "En unidades del SI, o en otras coherentes.",
    "path": "Su trayectoria",
    "speed_of_0_or": "Una velocidad de 0 o más, un ángulo desde la vertical hacia abajo hasta la vertical hacia arriba, una altura de 0 o más y g mayor que 0.",
    "path_2": "Trayectoria",
    "no_air_angles_in": "Sin aire. Ángulos en {unitWord}.",
    "radius_and_v_above": "El radio y la {v} son mayores que 0.",
    "speed_2": "velocidad",
