    "genetics": "Genética",
    "punnett_squares_of_up": "Cuadros de Punnett de hasta seis genes, dibujados, y del X; Hardy-Weinberg, a partir de p, de recuentos con su prueba χ², o del rasgo recesivo; χ² de un cruce; mapas genéticos de dos genes o tres, con el cromosoma dibujado; las probabilidades de la descendencia; heredabilidad, por la ecuación del criador; epistasia y qué proporción se ajusta; riesgo genético, con la familia dibujada como un pedigrí; y grupos sanguíneos.",
    "sequence_s_length_bases": "La longitud de una secuencia, sus bases, el GC a lo largo de ella y su masa, con su complementaria y complementaria inversa; traducción en seis pautas y los marcos abiertos de lectura, dibujados; la rueda de codones; la T<sub>m</sub> de cebadores por vecinos más próximos, con su fusión dibujada; ADN y ARN por A<sub>260</sub> y su pureza; masa, moles y copias; ligación, con el plásmido dibujado; digestiones de restricción corridas en un gel; las copias de la PCR, ciclo a ciclo; alineamientos, global y local, con un diagrama de puntos; guías CRISPR; motivos con los códigos IUPAC; cebadores para mutagénesis y ensamblaje de Gibson; y genomas y sus copias.",
    "protein_s_mass_pi": "La masa, pI, carga, extinción e hidropatía de una proteína, dibujadas; los veinte aminoácidos, con la valoración de cada uno dibujada; concentración de proteína por A<sub>280</sub> o una curva patrón; cinética enzimática, de V<sub>max</sub> y K<sub>m</sub> o ajustada a puntos, con inhibidores y el diagrama de Lineweaver-Burk; unión por Hill; dosis-respuesta, con su IC<sub>50</sub> ajustada; y una tabla de purificación.",
    "lab": "Laboratorio",
    "c_v_c_v": "C₁V₁ = C₂V₂ y diluciones seriadas, con sus tubos dibujados; preparar una solución, a partir de su molaridad, fórmula, porcentaje o una solución concentrada; recuento de células; crecimiento y duplicación, y OD<sub>600</sub>; colonias y UFC/mL; las RPM y g de la centrífuga; una mezcla maestra de PCR; qPCR por ΔΔCt y su curva patrón; la media ± 2 EE con barras de error; R<sub>f</sub> de cromatografía; el microscopio; tamaños a partir de un gel; eficiencia de transformación; siembra de placas; MOI; radioisótopos; y tampones.",
    "water_potential_osmolarity_and": "Potencial hídrico, osmolaridad y tonicidad, con un glóbulo rojo dibujado; relación superficie-volumen; Q₁₀; difusión por Fick; potenciales de membrana por Nernst y por Goldman; energía libre; el gasto del corazón y la presión arterial, dibujados; y respiración, su ATP y el cociente respiratorio.",
    "health": "Salud",
    "diagnostic_tests_their_sensitivity": "Pruebas diagnósticas, su sensibilidad, especificidad y valores predictivos, con mil personas dibujadas; riesgos y odds ratios con sus intervalos, y el número necesario para tratar; una epidemia por SIR y la inmunidad de grupo; oxígeno y hemoglobina, con el desplazamiento de Bohr dibujado; un potencial de acción por Hodgkin y Huxley; los riñones, TFGe y aclaramiento; IMC y energía; y los niveles de un fármaco a lo largo de sus dosis. Para aprender, no para atender pacientes.",
    "ecology": "Ecología",
    "population_growth_exponential_and": "Crecimiento de poblaciones, exponencial y logístico; depredadores y presas por Lotka y Volterra; marcado y recaptura; diversidad por Simpson y Shannon; tablas de vida y supervivencia; pirámides de energía; productividad primaria; selección natural y deriva genética, generación a generación; matrices de Leslie; competencia; especies, área y rarefacción; árboles por UPGMA y unión de vecinos; y el reloj molecular.",
    "opens_card_of_physics": "Abre la tarjeta del panel de Física que calcula esto, con lo que escribiste en ella: allí puedes hallar cualquiera de sus letras a partir de las demás.",
    "opens_card_of_finance": "Abre la tarjeta de la pestaña Finanzas de Resolver que calcula esto, con lo que escribiste en ella, y lo que más da.",
    "opens_card_of_biology": "Abre la tarjeta del panel de Biología que calcula esto, con lo que escribiste en ella, y la dibuja.",
    "elastic": "Elástico",
    "they_bounce_apart_as": "Rebotan y se separan, como las bolas de billar, y no se pierde energía cinética.",
    "they_go_on_as": "Siguen como una sola: se conserva la cantidad de movimiento, y se pierde toda la energía cinética que se puede.",
    "pop_out": "Separar",
    "panel_as_big_as": "El panel tan grande como la página, con sus tarjetas en una lista y la abierta al lado; en la extensión, en una ventana propia.",
    "pop_in": "Volver a unir",
    "panel_back_in_calculator": "El panel de nuevo en la calculadora.",
    "periodic_table_as_big": "La tabla periódica tan grande como la página, cada elemento con su número, nombre y masa; en la extensión, en una ventana propia.",
    "table_whole_width_click": "La tabla a todo lo ancho. Haz clic en un elemento para abrirlo de nuevo.",
    "table_back_in_calculator": "La tabla de nuevo en la calculadora.",
    "all_118_elements_point": "Los 118 elementos. Señala uno para verlo sobre la tabla, haz clic en él para ver todo lo que se sabe de él y de su átomo; las teclas de flecha pasan de uno al siguiente.",
    "molar_mass_of_formula_2": "La masa molar de una fórmula y la parte de cada elemento en ella; gramos, moles y partículas; y la fórmula empírica y molecular de una composición.",
    "equation_balanced_with_kind": "Una ecuación ajustada, con su tipo y lo que oxida y reduce; las cantidades de una reacción, su reactivo limitante y rendimiento porcentual; una hoja de ejercicios; calor, q = mcΔT; y semivida.",
    "solutions": "Disoluciones",
    "molarity_dilution_freezing_and": "Molaridad, dilución, el punto de congelación y de ebullición de una disolución, pH, pOH, [H⁺] y [OH⁻], ácidos y bases débiles, tampones, y qué se disuelve en agua.",
    "common_ions_monatomic_and": "Los iones comunes, monoatómicos y poliatómicos: la carga y masa molar de cada uno, su color en agua y en la llama; el nombre de una fórmula y la fórmula de un nombre; y números de oxidación.",
    "ideal_gas_law_pv": "La ley de los gases ideales, PV = nRT, con la masa y densidad de un gas; la ley combinada de los gases; presiones parciales; un gas recogido sobre agua; los volúmenes de los gases de una reacción; efusión; el aire con la altura; y la velocidad del sonido.",
    "clear_search": "Borrar la búsqueda",
    "every_element_bright_again": "Todos los elementos de nuevo brillantes.",
    "each_kind_of_element": "Cada tipo de elemento con su color: metales alcalinos, metales de transición, halógenos, gases nobles… Haz clic en uno bajo la tabla para iluminar solo sus elementos.",
    "solid_liquid_or_gas": "Sólido, líquido o gas a 20 °C.",
    "subshell_last_electrons_go": "El subnivel en que entran sus últimos electrones: s, p, d o f.",
    "electronegativity": "Electronegatividad",
    "how_strongly_pulls_electrons": "Con qué fuerza atrae electrones en un enlace, en la escala de Pauling: azul para poca, rojo para mucha. El flúor atrae más, 3.98.",
    "slide_and_each_element": "Desplázala y cada elemento es sólido, líquido o gas como lo es a esa temperatura, a 1 atm, según sus puntos de fusión y ebullición. Haz clic en la temperatura para volver a 20 °C.",
    "from_to": "Desde – hasta",
    "drag_either_end_of": "Arrastra cualquier extremo de la escala y los elementos fuera de ella se atenúan, para ver cuáles están entre dos números. Haz clic en un número para ver todos de nuevo.",
    "boiling_point": "Punto de ebullición",
    "where_boils_in_c": "Dónde hierve, en °C: azul para bajo, rojo para alto. El helio hierve más abajo, −269 °C; el wolframio más arriba, cerca de 5930 °C.",
    "atomic_radius": "Radio atómico",
    "how_big_atom_van": "Qué tamaño tiene su átomo, su radio de van der Waals en pm: aguamarina para pequeño, lavanda para grande. Crece al bajar en un grupo y disminuye a lo largo de un periodo.",
    "electron_affinity": "Afinidad electrónica",
    "energy_given_off_as": "La energía que libera al captar un electrón su átomo, en kJ/mol: pálido para poca, verde para mucha. El cloro libera más, 349; los gases nobles no captan ninguno.",
