    "discovered": "Descubrimiento",
    "year_was_found_sand": "El año en que se halló: arena para los elementos conocidos desde la antigüedad, violeta para los más nuevos, hechos en laboratorios.",
    "change_unit": "Cambiar la unidad",
    "next_unit_for_every": "La siguiente unidad, para cada número de su tipo: °C, °F y K; kJ/mol y eV; g/cm³, kg/m³ y lb/ft³; la masa atómica completa o con 3 decimales.",
    "ionization_energy": "Energía de ionización",
    "energy_to_take_one": "La energía para arrancar un electrón de cada átomo de un mol de él, en kJ/mol: verde para poca, púrpura para mucha. El helio es el que más se aferra, 2372.",
    "melting_point": "Punto de fusión",
    "where_melts_in_c": "Dónde funde, en °C: azul para bajo, rojo para alto. El carbono funde más arriba, cerca de 3550 °C.",
    "mass_in_each_cm": "Su masa en cada cm³: pálido para ligero, marrón para pesado. El osmio es el más pesado, 22.6 g/cm³; los gases están todos cerca de 0.",
    "atomic_number": "Número atómico",
    "protons_in_nucleus_of": "Los protones en el núcleo de cada átomo, que lo hacen este elemento; tantos electrones a su alrededor en el átomo neutro. La tabla sigue su orden.",
