    "mean_mass_of_atoms": "La masa media de sus átomos, tal como se hallan en la naturaleza, en g/mol: un mol de él pesa tantos gramos. Entre [ ], un elemento sin isótopo estable: el número másico del de vida más larga.",
    "how_strongly_atom_pulls": "Con qué fuerza su átomo atrae los electrones de un enlace, en la escala de Pauling, del 0.79 del cesio al 3.98 del flúor. Los gases nobles, con pocos enlaces, no tienen.",
