    "how_big_atom_van_2": "Qué tamaño tiene su átomo: su radio de van der Waals, en picómetros, 10⁻¹² m.",
    "energy_given_off_as_2": "La energía que libera cada átomo de un mol de él, como gas, al captar un electrón. Negativa, el ion que formaría se desintegra: una estimación.",
