    "unpaired_electrons": "Electrones desapareados",
    "electrons_alone_in_their": "Sus electrones solos en sus orbitales, por la regla de Hund: lo que hace magnético a un átomo.",
    "energy_to_warm_gram": "La energía para calentar un gramo de él 1 K, a 25 °C: q = mcΔT. No medida para la mayoría de los elementos radiactivos.",
    "when_was_found_by": "Cuándo se halló, por quién, y quién lo obtuvo puro por primera vez.",
    "isotopes": "Isótopos",
    "stable_isotopes_commonest_first": "Sus isótopos estables, el más común primero; sin ninguno estable, los que se hallan en la naturaleza, o el de vida más larga y su semivida.",
    "where_name_comes_from": "De dónde viene su nombre, y cómo se descubrió.",
