    "heat_of_vaporization": "Calor de vaporización",
    "energy_to_boil_mole": "La energía para hervir un mol de él en su punto de ebullición, sin cambio de temperatura.",
    "thermal_conductivity": "Conductividad térmica",
    "how_well_heat_flows": "Lo bien que fluye el calor a través de él: vatios a través de un metro de él por cada kelvin entre sus extremos, a través de un metro cuadrado. La plata y el cobre los que más, los gases los que menos.",
    "electrical_resistivity": "Resistividad eléctrica",
    "how_much_resists_current": "Cuánto se opone a una corriente, a 20 °C: R = ρL/A. Pequeña en los metales, la de la plata, 1.6 × 10⁻⁸ Ω·m, la menor; enorme en un aislante como el azufre.",
    "mohs_hardness": "Dureza de Mohs",
    "how_hard_by_what": "Su dureza, según lo que raya y por lo que es rayado, del 1 del talco al 10 del diamante.",
    "cas_number": "Número CAS",
    "number_in_chemical_abstracts": "Su número en el registro del Chemical Abstracts Service, que nombra cada sustancia una sola vez: para buscarla en cualquier parte.",
    "magnetism": "Magnetismo",
    "how_acts_in_magnetic": "Cómo se comporta en un campo magnético: ferromagnético, como el hierro, un imán él mismo; paramagnético, atraído débilmente; diamagnético, repelido débilmente; antiferromagnético, con el magnetismo de sus átomos anulándose.",
    "crystal_structure": "Estructura cristalina",
    "how_atoms_packed_in": "Cómo se empaquetan sus átomos en el sólido, a temperatura ambiente. Dibujada debajo, su celda unidad, la caja más pequeña que se repite, o en una hexagonal un prisma de 3; sus átomos contados por su parte: uno en un vértice lo comparten 8 cajas, o 6 prismas, en una cara 2. Bolas grises: solo su red, con muchos átomos en cada punto.",
    "abundance_in_crust": "Abundancia en la corteza",
    "how_much_of_earth": "Cuánto hay de él en la corteza terrestre, en mg/kg, partes por millón en masa: el oxígeno casi la mitad, luego el silicio. Solo trazas: unos pocos átomos a la vez, formados en minerales de uranio y torio; sintético: fabricado solo en el laboratorio.",
    "appearance": "Aspecto",
    "what_looks_like_pure": "Cómo es, puro, a temperatura ambiente.",
    "light_of_atoms_as": "La luz de sus átomos como gas, del violeta a 380 nm al rojo a 750: absorción, luz blanca que lo atraviesa, con líneas oscuras en el arco iris donde quita colores; emisión, calentado o en una chispa, esos mismos colores solos, brillantes sobre negro. Cada elemento tiene líneas propias, como una huella dactilar: por eso el helio se halló en el Sol antes que en la Tierra. Sus líneas más fuertes, según las lista NIST, cuanto más fuertes más anchas; de un elemento cuyo átomo no tiene aquí, las de su ion. Haz clic: la otra.",
    "alkali_metal": "Metal alcalino",
    "group_1_but_hydrogen": "Grupo 1 salvo el hidrógeno: metales blandos que reaccionan con violencia con el agua, dando hidróxidos e hidrógeno. Un electrón externo, perdido como ion 1+.",
    "alkaline_earth_metal": "Metal alcalinotérreo",
    "group_2_reactive_metals": "Grupo 2: metales reactivos, menos que los alcalinos. Dos electrones externos, perdidos como ion 2+.",
    "transition_metal": "Metal de transición",
    "groups_3_to_12": "Grupos 3 a 12, que llenan subniveles d: metales duros, con muchos estados de oxidación y compuestos coloreados; buenos catalizadores.",
    "post_transition_metal": "Metal postransicional",
    "metals_after_transition_metals": "Los metales posteriores a los de transición: más blandos, con puntos de fusión más bajos, algunos con óxidos tanto ácidos como básicos.",
    "metalloid": "Metaloide",
    "between_metals_and_nonmetals": "Entre los metales y los no metales: semiconductores, como el silicio y el germanio.",
    "nonmetal": "No metal",
    "poor_conductors_of_heat": "Malos conductores del calor y la electricidad, gases o sólidos quebradizos, que toman o comparten electrones en sus compuestos.",
    "halogen": "Halógeno",
    "group_17_reactive_nonmetals": "Grupo 17: no metales reactivos, a un electrón de una capa llena, que toman como ion 1−; con metales forman sales.",
    "noble_gas": "Gas noble",
