    "actinium_to_lawrencium_filling": "Del actinio al lawrencio, llenando el subnivel 5f: todos radiactivos; solo el torio y el uranio son comunes en la naturaleza.",
    "draws_up_to_25": "Dibuja hasta 25 funciones de x, con un control deslizante para cualquier otra letra, como a en a x^2 + b: x^2 – 3, 2sin(x); sucesiones, a(n) = a(n – 1) + 2 {a(1) = 1}; y campos de pendientes, dy/dx = x – y {y(0) = 1}, un clic añade una solución. Marca raíces, máximos, mínimos e intersecciones. Arrastra para mover, desplaza o pellizca para hacer zoom; señala una curva para ver sus valores, haz clic para su tangente. La pestaña Tabla las lista.",
