    "open_mode": "Modo de apertura",
    "what_toolbar_icon_and": "Lo que abren el icono de la barra de herramientas y Alt+S: Fijo, la ventana emergente bajo el icono; Independiente, la calculadora en su propia ventana, que crece o se encoge con ella; o Avanzado, la calculadora separada en una ventana grande con las herramientas a su lado, cuyo botón Volver a unir la devuelve al modo Independiente. Abrir abre el modo elegido; el modo Independiente y el modo Avanzado también están en el menú del icono de la barra de herramientas, y el modo Independiente en el botón de la página.",
    "fixed": "Fijo",
