    "language_of_calculator_s": "El idioma de las palabras de la calculadora: sus menús, consejos, tarjetas y resultados. Auto sigue el idioma del navegador. Los números y los nombres de las teclas se quedan como están.",
    "calculator_button_on_every": "Botón de la calculadora en todos los sitios web",
    "small_calculator_button_on": "Un pequeño botón de calculadora en el lado de cada página que abre el modo Independiente. Arrástralo a cualquier lado; conserva su lugar en todas las ventanas.",
    "browser_asks_for_access": "El navegador pide acceso a los sitios web al activarlo. Solo se añade el botón; no se lee nada de las páginas.",
    "inline_instant_answers_on": "Respuestas instantáneas en línea en todos los sitios web",
    "small_icon_after_maths": "Un pequeño icono tras las operaciones de cualquier página: pasa el puntero por encima para ver la respuesta, haz clic para abrirla en la calculadora. Selecciona cualquier texto, o haz clic derecho sobre él, para calcularlo también.",
