    "h_t_calculates_hyperbolic": "[h, t] Calcula la tangente hiperbólica de un valor.",
    "h_shift_t_calculates": "[h, Shift+T] Calcula la tangente hiperbólica inversa de un valor. (Disponible cuando se pulsa el botón",
    "e_raises_constant_e": "[e] Eleva la constante «e» (2.718281828459045…) a la potencia de un valor.",
