    "on_october_16_2006": "El 16 de octubre de 2006, científicos que trabajaban en el Instituto Conjunto de Investigaciones Nucleares de Dubná, Rusia, junto con científicos del Laboratorio Nacional Lawrence Livermore del Departamento de Energía de EE. UU., anunciaron la creación del oganesón.",
